import {
  collides,
  brickHit,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

// --- Issue #1: brick bounce -------------------------------------------------
// The ball must bounce off bricks (per face, corner, push-out, neighbours and
// tunnelling). These tests were written red BEFORE the fix landed.

function hitBrick(x, y, row = 2) {
  return { x, y, w: 72, h: 20, alive: true, row, points: (5 - row) * 10 };
}

test('brickHit: top-face hit flips vy and pushes the ball out', () => {
  const brick = hitBrick(100, 100);
  const ball = { x: 136, y: 110, r: 7, vx: 0, vy: 120, prevX: 136, prevY: 104 };
  const hits = brickHit(ball, [brick]);
  assert.equal(hits.length, 1);
  assert.equal(brick.alive, false);
  assert.ok(ball.vy < 0, 'vy should flip upward after a top-face hit');
  assert.equal(ball.vx, 0, 'vx must be left untouched');
  assert.equal(collides(ball, brick), false, 'ball must be pushed out of the brick');
});

test('brickHit: bottom-face hit flips vy downward', () => {
  const brick = hitBrick(100, 100);
  const ball = { x: 136, y: 126, r: 7, vx: 0, vy: -120, prevX: 136, prevY: 132 };
  const hits = brickHit(ball, [brick]);
  assert.equal(hits.length, 1);
  assert.ok(ball.vy > 0, 'vy should flip downward after a bottom-face hit');
  assert.equal(collides(ball, brick), false);
});

test('brickHit: side hit flips vx and leaves vy alone', () => {
  const brick = hitBrick(100, 100);
  const ball = { x: 96, y: 110, r: 7, vx: -120, vy: 0, prevX: 102, prevY: 110 };
  const hits = brickHit(ball, [brick]);
  assert.equal(hits.length, 1);
  assert.ok(ball.vx > 0, 'vx should flip after a side hit');
  assert.equal(ball.vy, 0, 'vy must be left untouched');
  assert.equal(collides(ball, brick), false, 'ball must be pushed out of the brick');
});

test('brickHit: equal penetrations = corner hit, flips both components', () => {
  const brick = hitBrick(100, 100);
  const ball = { x: 96, y: 96, r: 7, vx: 100, vy: 100, prevX: 90, prevY: 90 };
  const hits = brickHit(ball, [brick]);
  assert.equal(hits.length, 1);
  assert.ok(ball.vx < 0 && ball.vy < 0, 'corner hit flips both components');
  assert.equal(collides(ball, brick), false);
});

test('brickHit: seam hit destroys both bricks, velocity flips exactly once', () => {
  const top = hitBrick(100, 100);
  const bottom = hitBrick(100, 128, 1);
  const ball = { x: 136, y: 122, r: 7, vx: 0, vy: 120, prevX: 136, prevY: 100 };
  const hits = brickHit(ball, [top, bottom]);
  assert.equal(hits.length, 2);
  assert.equal(top.alive, false);
  assert.equal(bottom.alive, false);
  assert.ok(ball.vy < 0, 'vy must flip exactly once (stays negative, not double-flipped)' );
});

test('brickHit: fast ball tunnelling through a brick is still caught', () => {
  // ballSpeed(6) = 710 px/s with a 50 ms cap => 35.5 px/step, more than the
  // ~34 px needed to cross BRICK_H + 2r. The brick must still be hit.
  const brick = hitBrick(100, 100);
  const ball = { x: 250, y: 110, r: 7, vx: 300, vy: 0, prevX: 60, prevY: 110 };
  const hits = brickHit(ball, [brick]);
  assert.equal(hits.length, 1);
  assert.equal(brick.alive, false);
  assert.ok(ball.vx < 0, 'tunnelling ball bounces off the brick');
});

