// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: brick collision lives in
// the pure `brickHit()` helper (see below).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember where the ball was BEFORE this move: `brickHit()` sweeps the
  // segment between the two positions so a fast ball cannot tunnel through a
  // brick between two frames (issue #1).
  ball.prevX = ball.x;
  ball.prevY = ball.y;

  ball.x += ball.vx * dt;

