// --- Brick collision (issue #1: a real per-face bounce) --------------------

// True if the ball (circle approximated by its box) overlaps the brick.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Slab sweep of the ball's path between its previous and current positions
// against the brick inflated by the ball radius (a point swept against the
// inflated box is the same set as the ball's box swept along the segment).
// Returns null on a miss, otherwise the earliest entry time `t` plus, per
// axis, the time the path crossed into the brick's slab (`null` when it never
// left the slab). Used so a fast ball that jumps over a brick in one frame is
// still caught (tunnelling, issue #1).
function sweptEntry(ball, brick) {
  const left = brick.x - ball.r;
  const right = brick.x + brick.w + ball.r;
  const top = brick.y - ball.r;
  const bottom = brick.y + brick.h + ball.r;
  const dx = ball.x - ball.prevX;
  const dy = ball.y - ball.prevY;

  let tEnter = 0;
  let tExit = 1;
  let entryX = null;
  let entryY = null;

  if (dx === 0) {
    if (ball.prevX < left || ball.prevX > right) return null;
  } else {
    let t1 = (left - ball.prevX) / dx;
    let t2 = (right - ball.prevX) / dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    entryX = t1;
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
    if (tEnter > tExit) return null;
  }

  if (dy === 0) {
    if (ball.prevY < top || ball.prevY > bottom) return null;
  } else {
    let t1 = (top - ball.prevY) / dy;
    let t2 = (bottom - ball.prevY) / dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    entryY = t1;
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
    if (tEnter > tExit) return null;
  }

  if (tEnter > 1) return null;
  return { t: tEnter, entryX, entryY };
}

// Axis to bounce on for a ball CURRENTLY overlapping the brick: the face with
// the SMALLER penetration was the one hit. Equal penetrations = corner hit.
function penetrationAxis(ball, brick) {
  const overlapX = Math.min(
    ball.x + ball.r - brick.x,
    brick.x + brick.w - (ball.x - ball.r)
  );
  const overlapY = Math.min(
    ball.y + ball.r - brick.y,
    brick.y + brick.h - (ball.y - ball.r)
  );
  if (Math.abs(overlapX - overlapY) < 1e-9) return 'both';
  return overlapX < overlapY ? 'x' : 'y';
}

// Axis to bounce on for a ball that swept THROUGH the brick without currently
// overlapping it (tunnelling): the face crossed last is the one entered
// through — flip that axis and leave the other component untouched.
function entryAxis(swept) {
  const { entryX, entryY } = swept;
  if (entryX === null && entryY === null) return 'both'; // started inside (defensive)
  if (entryX === null) return 'y';
  if (entryY === null) return 'x';
  if (Math.abs(entryX - entryY) < 1e-9) return 'both';
  return entryX > entryY ? 'x' : 'y';
}

// Repositions the ball just outside the face it entered through (using the
// INCOMING direction, i.e. before the bounce): the ball never re-overlaps the
// brick on the next frame, which would re-flip the velocity forever (sticky
// bounce). Only meaningful while the ball still overlaps the brick.
function pushOut(ball, brick, axis, vx, vy) {
  if (axis === 'x' || axis === 'both') {
    if (vx > 0) ball.x = brick.x - ball.r;
    else if (vx < 0) ball.x = brick.x + brick.w + ball.r;
  }
  if (axis === 'y' || axis === 'both') {
    if (vy > 0) ball.y = brick.y - ball.r;
    else if (vy < 0) ball.y = brick.y + brick.h + ball.r;
  }
}

// Pure brick collision resolution (issue #1). Sweeps the ball's path since its
// previous position against every live brick, destroys the bricks it touches
// and applies the bounce EXACTLY ONCE, on the axis of the earliest hit — the
// grid gap (8 px) is narrower than the ball (14 px), so a seam overlap hits
// two bricks in the same pass and a double flip would cancel out and let the
// ball plow straight through.
// Returns the destroyed bricks, in iteration order.
export function brickHit(ball, bricks) {
  const hits = [];
  let primary = null;

  for (const brick of bricks) {
    if (!brick.alive) continue;

    const hasPrev = Number.isFinite(ball.prevX) && Number.isFinite(ball.prevY);
    let info = null;
    if (hasPrev) {
      const swept = sweptEntry(ball, brick);
      if (swept) {
        const axis = collides(ball, brick)
          ? penetrationAxis(ball, brick)
          : entryAxis(swept);
        info = { t: swept.t, axis };
      }
    } else if (collides(ball, brick)) {
      info = { t: 0, axis: penetrationAxis(ball, brick) };
    }
    if (!info) continue;

    brick.alive = false;
    hits.push(brick);
    if (!primary || info.t < primary.t) primary = { brick, axis: info.axis };
  }

  if (primary) {
    const { brick, axis } = primary;
    const vx = ball.vx; // incoming direction, BEFORE the flip
    const vy = ball.vy;
    if (collides(ball, brick)) pushOut(ball, brick, axis, vx, vy);
    if (axis === 'x' || axis === 'both') ball.vx = -vx;
    if (axis === 'y' || axis === 'both') ball.vy = -vy;
  }

  return hits;
}

