// Repositions the ball just outside the face it entered through: the ball must
// not overlap the brick on the next frame, or the velocity would re-flip
// forever (sticky bounce). Only meaningful while the ball still overlaps the
// brick.
// Direction = the face with the SMALLER penetration (minimum translation
// vector); when the ball is centered on an axis, fall back to the incoming
// direction of travel so the ball is pushed back the way it came.
function pushOut(ball, brick, axis, vx, vy) {
  if (axis === 'x' || axis === 'both') {
    const throughLeft = ball.x + ball.r - brick.x;
    const throughRight = brick.x + brick.w - (ball.x - ball.r);
    const push = Math.min(throughLeft, throughRight) + 0.5;
    if (throughLeft < throughRight) ball.x -= push;
    else if (throughRight < throughLeft) ball.x += push;
    else ball.x += vx > 0 ? -push : push; // centered: push back the way it came
  }
  if (axis === 'y' || axis === 'both') {
    const throughTop = ball.y + ball.r - brick.y;
    const throughBottom = brick.y + brick.h - (ball.y - ball.r);
    const push = Math.min(throughTop, throughBottom) + 0.5;
    if (throughTop < throughBottom) ball.y -= push;
    else if (throughBottom < throughTop) ball.y += push;
    else ball.y += vy > 0 ? -push : push; // centered: push back the way it came
  }
}

